"""Writes Allowlist.swift for bench-reader.

    python -m bench.allowlist config/agents.yaml > Allowlist.swift
"""

import sys
from pathlib import Path

from bench.config import Agent, ConfigError, load_agents


def render(agents: dict[str, Agent]) -> str:
    lines = [
        "// Generated by bench.allowlist from agents.yaml. Do not edit.",
        "let allowlist: [(agent: String, handle: String)] = [",
        *(f'    (agent: "{a.name}", handle: "{a.handle}"),' for a in agents.values()),
        "]",
    ]
    return "\n".join(lines) + "\n"


def main(argv: list[str] | None = None) -> int:
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 1:
        print("usage: python -m bench.allowlist AGENTS_YAML", file=sys.stderr)
        return 64
    try:
        agents = {n: a for n, a in load_agents(Path(argv[0])).items() if a.channel == "imessage"}
    except (ConfigError, OSError) as e:
        print(f"bench.allowlist: {e}", file=sys.stderr)
        return 1
    if not agents:
        print(f"bench.allowlist: no iMessage agent in {argv[0]} has a handle yet", file=sys.stderr)
        return 1
    sys.stdout.write(render(agents))
    return 0


if __name__ == "__main__":
    sys.exit(main())
